it('parse timestamp, js Date, Day.js object', () => {
  const d = '2014-06-01T12:00:00Z'
  const tz = 'America/Los_Angeles'
  const m = moment(d).tz(tz)
  const ts = m.valueOf()
  const j = dayjs(ts)
  const D = new Date(ts)
  expect(dayjs.tz(ts, tz).format()).toBe(m.format())
  expect(dayjs.tz(D, tz).format()).toBe(m.format())
  expect(dayjs.tz(j, tz).format()).toBe(m.format())
})
```

